import pytest
from candidate import remove_vowels


def test_remove_vowels_empty_string_returns_empty_string():
    assert remove_vowels('') == ''


def test_remove_vowels_all_consonants_returns_same_string():
    assert remove_vowels('zbcd') == 'zbcd'


def test_remove_vowels_mixed_vowels_and_consonants():
    assert remove_vowels('abcdef') == 'bcdf'


def test_remove_vowels_all_lowercase_vowels_returns_empty():
    assert remove_vowels('aeiou') == ''


def test_remove_vowels_all_uppercase_vowels_returns_empty():
    assert remove_vowels('AEIOU') == ''


def test_remove_vowels_mixed_case_vowels():
    assert remove_vowels('aaBAA') == 'B'


def test_remove_vowels_preserves_newlines():
    assert remove_vowels("abcdef\nghijklm") == 'bcdf\nghjklm'


def test_remove_vowels_preserves_spaces():
    assert remove_vowels('a e i o u') == '   '


def test_remove_vowels_preserves_digits():
    assert remove_vowels('abc123def') == 'bc123df'


def test_remove_vowels_preserves_punctuation():
    assert remove_vowels('hello, world!') == 'hll, wrld!'


def test_remove_vowels_single_vowel_lowercase():
    assert remove_vowels('a') == ''


def test_remove_vowels_single_vowel_uppercase():
    assert remove_vowels('A') == ''


def test_remove_vowels_single_consonant():
    assert remove_vowels('b') == 'b'


def test_remove_vowels_multiple_repeated_vowels():
    assert remove_vowels('aaaaa') == ''


def test_remove_vowels_repeated_uppercase_vowels():
    assert remove_vowels('AAAAA') == ''


def test_remove_vowels_alternating_vowels_and_consonants():
    assert remove_vowels('ababab') == 'bbb'


def test_remove_vowels_all_e_vowels():
    assert remove_vowels('eee') == ''


def test_remove_vowels_all_i_vowels():
    assert remove_vowels('IiIi') == ''


def test_remove_vowels_all_o_vowels():
    assert remove_vowels('OoOo') == ''


def test_remove_vowels_all_u_vowels():
    assert remove_vowels('UuUu') == ''


def test_remove_vowels_preserves_tabs():
    assert remove_vowels('a\tb') == '\tb'


def test_remove_vowels_preserves_carriage_returns():
    assert remove_vowels('a\rb') == '\rb'


def test_remove_vowels_preserves_special_characters():
    assert remove_vowels('a@b#c$d%e') == '@b#d'


def test_remove_vowels_none_input_raises_type_error():
    with pytest.raises(TypeError):
        remove_vowels(None)


def test_remove_vowels_integer_input_raises_type_error():
    with pytest.raises(TypeError):
        remove_vowels(12345)


def test_remove_vowels_list_input_raises_type_error():
    with pytest.raises(TypeError):
        remove_vowels(['a', 'b', 'c'])


def test_remove_vowels_float_input_raises_type_error():
    with pytest.raises(TypeError):
        remove_vowels(3.14)


def test_remove_vowels_boolean_input_raises_type_error():
    with pytest.raises(TypeError):
        remove_vowels(True)


def test_remove_vowels_returns_string_type():
    result = remove_vowels('hello')
    assert isinstance(result, str)


def test_remove_vowels_long_string_with_many_vowels():
    text = 'a' * 1000 + 'bc' + 'e' * 1000
    assert remove_vowels(text) == 'bc'


def test_remove_vowels_underscore_preserved():
    assert remove_vowels('a_b_c') == '_b_c'


def test_remove_vowels_mixed_upper_lower_consonants_and_vowels():
    assert remove_vowels('Hello World') == 'Hll Wrld'
